import ar from './ar.js'

// Gettext-style: the English sentence is the key. Missing translations fall back to English, so the app never breaks.
// {name} placeholders are filled from the second argument:  t('Page {page} of {pages}', { page: 1, pages: 3 })
// Texts generated by the server in English (notifications, match reasons, errors) are matched against the same
// dictionary: a key such as 'Same color: {x}' also translates 'Same color: Black'.
export const LANGS = {
  en: { label: 'English', dir: 'ltr', locale: 'en' },
  ar: { label: 'العربية', dir: 'rtl', locale: 'ar-EG' },
}
const DICTS = { en: {}, ar }
export const STORAGE_KEY = 'findit.lang'
let current = 'en'
const patternCache = {}

export function setLanguage(lang) { if (LANGS[lang]) current = lang }
export function currentLocale() { return LANGS[current].locale }

function interpolate(text, vars) {
  return vars ? text.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : text
}

function patterns(lang) {
  if (!patternCache[lang]) {
    patternCache[lang] = Object.keys(DICTS[lang]).filter((k) => k.includes('{')).map((k) => {
      const names = []
      const source = k.replace(/[.*+?^$()|[\]\\]/g, '\\$&').replace(/\{(\w+)\}/g, (m, n) => { names.push(n); return '(.+?)' })
      return { re: new RegExp(`^${source}$`), names, value: DICTS[lang][k] }
    })
  }
  return patternCache[lang]
}

/** Usable anywhere (components, services, validation). Uses the language last set by the provider. */
export function translate(key, vars) {
  if (typeof key !== 'string' || !key) return key
  const dict = DICTS[current]
  if (!dict) return interpolate(key, vars)
  if (dict[key]) return interpolate(dict[key], vars)
  if (!vars) {
    for (const p of patterns(current)) {
      const m = p.re.exec(key)
      if (m) {
        const found = {}
        p.names.forEach((n, i) => { found[n] = translate(m[i + 1]) })
        return interpolate(p.value, found)
      }
    }
  }
  return interpolate(key, vars)
}

export function detectLanguage() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved && LANGS[saved]) return saved
  } catch { /* storage can be blocked */ }
  try { if ((navigator.language || '').toLowerCase().startsWith('ar')) return 'ar' } catch { /* ignore */ }
  return 'en'
}
